 $('#trainBtn').textContent='属性加点'+(h.points?' +'+h.points:'');$('#abilities').innerHTML=`<button class="ability" data-skill="attack"><kbd>J</kbd><i>⚔</i><small>普通攻击</small></button>`+['q','e','r'].map((s,i)=>`<button class="ability ${i===2?'special':''}" data-skill="${i}" title="${d.skills[i]} / 消耗 ${[18,28,52][i]} 法力"><kbd>${s.toUpperCase()}</kbd><i style="color:${d.color}">${[d.icon,'✧','✺'][i]}</i><small>${d[s]}</small>${a.cd[i]>0?'<span class="cd">'+Math.ceil(a.cd[i])+'</span>':i===2&&h.lv<3&&!h.skillsKept10?'<span class="cd" style="font-size:12px">Lv.3</span>':''}</button>`).join('')+`<button class="ability" data-skill="potion"><kbd>H</kbd><i>🧪</i><small>药剂 ×${S.potions}</small></button>`;$('#abilities').querySelectorAll('[data-skill]').forEach(b=>b.onclick=()=>{if(menu)return;const s=b.dataset.skill;if(s==='attack')attack(active(),true);else if(s==='potion')potion();else skill(S.active,+s,true)});
