function readSave(){try{let v=JSON.parse(localStorage.getItem(SAVE_KEY)||localStorage.getItem('wuxing-chronicles-v23')||localStorage.getItem('wuxing-chronicles-v22')||localStorage.getItem('wuxing-chronicles-v21')||localStorage.getItem('wuxing-chronicles-v20')||localStorage.getItem('wuxing-chronicles-v19')||localStorage.getItem('wuxing-chronicles-v18')||localStorage.getItem('wuxing-chronicles-v17')||localStorage.getItem('wuxing-chronicles-v16')||localStorage.getItem('wuxing-chronicles-v15')||localStorage.getItem('wuxing-chronicles-v14')||localStorage.getItem('wuxing-chronicles-v13')||localStorage.getItem('wuxing-chronicles-v12')||localStorage.getItem('wuxing-chronicles-v11')||localStorage.getItem('wuxing-chronicles-v10')||localStorage.getItem('wuxing-chronicles-v9')||localStorage.getItem('wuxing-chronicles-v8')||localStorage.getItem('wuxing-chronicles-v7')||localStorage.getItem('wuxing-chronicles-v6')||localStorage.getItem('wuxing-chronicles-v5')||localStorage.getItem('wuxing-chronicles-v4')||localStorage.getItem('wuxing-chronicles-v2')||localStorage.getItem('wuxing-chronicles-v1'));return validateSave(v)?v:null}catch{return null}}
function validateSave(v){if(!v||![1,2].includes(v.version)||typeof v.name!=='string'||v.name.length>24||!Number.isInteger(v.active)||v.active<0||v.active>4)return false;
 const num=(n,min,max)=>typeof n==='number'&&Number.isFinite(n)&&n>=min&&n<=max;
 if(!num(v.gold,0,1e9)||!num(v.potions,0,1e5)||!Number.isInteger(v.chapter)||!num(v.chapter,0,4)||!num(v.nextItem,1,1e9)||!num(v.totalKills,0,1e8)||!num(v.death,0,1e7)||!num(v.played,0,1e10))return false;
 if(!Array.isArray(v.heroes)||v.heroes.length!==5||!Array.isArray(v.bosses)||v.bosses.length!==5||v.bosses.some(b=>typeof b!=='boolean')||!Array.isArray(v.kills)||v.kills.length!==5||v.kills.some(n=>!num(n,0,1e8))||!Array.isArray(v.chests)||v.chests.some(n=>!Number.isInteger(n)||n<0||n>4))return false;
 const item=it=>it===null||it&&Number.isInteger(it.id)&&num(it.id,1,1e9)&&Number.isInteger(it.slot)&&num(it.slot,0,v.version===1?2:5)&&Number.isInteger(it.tier)&&num(it.tier,0,3)&&num(it.power,1,10000);
 if(!Array.isArray(v.pets)||v.pets.length>1000||v.pets.some(p=>!p||!Number.isInteger(p.id)||!Number.isInteger(p.type)||!num(p.type,0,PETS.length-1)||!Number.isInteger(p.lv)||!num(p.lv,1,150)||!num(p.xp,0,1e8)))return false;
 if(new Set(v.pets.map(p=>p.id)).size!==v.pets.length)return false;
 if(v.heroes.some(h=>!h||typeof h.unlocked!=='boolean'||!Number.isInteger(h.lv)||!num(h.lv,1,250)||!num(h.xp,0,1e8)||!num(h.points,0,1e8)||!Array.isArray(h.bonus)||h.bonus.length!==3||h.bonus.some(n=>!Number.isInteger(n)||!num(n,0,1e6))||!Array.isArray(h.gear)||h.gear.length!==(v.version===1?3:6)||h.gear.some((it,k)=>!item(it)||(it&&it.slot!==k))||(h.pet!==null&&!v.pets.some(p=>p.id===h.pet))))return false;
 const assigned=v.heroes.map(h=>h.pet).filter(p=>p!==null);if(new Set(assigned).size!==assigned.length||!v.heroes[v.active].unlocked)return false;
 return Array.isArray(v.bag)&&v.bag.length<=999&&v.bag.every(i=>i&&item(i))&&v.position&&num(v.position.x,0,WW)&&num(v.position.y,0,WH)&&v.bosses.slice(0,v.chapter).every(Boolean)&&typeof v.won==='boolean'&&(!v.won||v.bosses.every(Boolean));}
function baseIntro(){let prior=readSave();showDialog(`<div class="kicker">一支队伍 · 五种力量 · 一场远征</div><h2 style="margin-top:10px">五行战记：灵脉远征</h2><p>五行灵脉被「无相」吞噬，四位守护者陷入沉睡。长老递给你一张地图，又偷偷塞了四瓶药：“拯救世界之前，记得吃饭。”<br>选择第一位战士，救出伙伴，驯服灵兽，重建五行之力。</p><label for="nickname" class="muted">冒险者昵称（无需账号，存档留在当前浏览器）</label><input id="nickname" type="text" maxlength="16" placeholder="给远征队起个名字" value=""><div class="choices" id="heroChoices">${HEROES.map((h,i)=>`<button class="choice ${i===startChoice?'selected':''}" data-choice="${i}"><b style="color:${h.color}">${h.element}</b><strong>${h.name} · ${h.title.slice(-2)}</strong><small>${h.main==='int'?'法术':h.main==='str'?'坦克':'敏捷'}</small></button>`).join('')}</div><p id="choiceDesc">${HEROES[startChoice].desc}。${HEROES[startChoice].skills[0]}</p><div class="actions"><button id="newGame" class="primary">踏上远征 →</button>${prior?'<button id="continue">继续已有远征</button>':''}<button id="introImport">导入存档</button></div><p class="muted">WASD 移动 / 点地移动 · J 进攻 / 默认被动迎击 · Q E R 技能 · F 互动<br>单人冒险，电脑队友跟随战斗；不用安装，也不用联网。</p>`,'start');if(prior)$('#nickname').value=prior.name;
 $('#heroChoices').querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{startChoice=+b.dataset.choice;$('#heroChoices').querySelectorAll('button').forEach(c=>c.classList.toggle('selected',c===b));$('#choiceDesc').textContent=HEROES[startChoice].desc+'。'+HEROES[startChoice].skills[0]});
 $('#newGame').onclick=()=>{const chosenName=$('#nickname').value.trim().slice(0,16)||'五行远征队';if(prior){showDialog('<h2>开始新的远征？</h2><p>当前浏览器已有存档。建议先导出备份；新远征开始后会覆盖自动存档。</p><div class="actions"><button id="backupOld">导出旧存档</button><button id="confirmNew" class="primary">确认开始新远征</button><button id="cancelNew">返回</button></div>','start');$('#backupOld').onclick=()=>exportSave(prior);$('#confirmNew').onclick=()=>begin(fresh(chosenName,startChoice));$('#cancelNew').onclick=intro}else begin(fresh($('#nickname').value.trim().slice(0,16)||'五行远征队',startChoice))};if(prior)$('#continue').onclick=()=>begin(prior);$('#introImport').onclick=importSave;}
function baseBegin(data){S=data;makeActors();makeWorld();menu=null;$('#curtain').classList.add('hidden');log=[];logMessage('长老：林地就在营地东边，先练练身手，别急着挑战妖王。');refreshBars();saveGame(false);canvas.focus({preventScroll:true});}
function switchHero(i){if(!S||menu)return;if(!owned(i)){logMessage('推进主线、击败守护者后，将有新伙伴加入。');return}if(actors[i].hp<=0){logMessage('这位伙伴暂时倒下了，回营地即可恢复。');return}S.active=i;destination=null;refreshBars();tone(550,.06);}
function awardXp(amount){for(let i=0;i<5;i++)if(owned(i)){let h=S.heroes[i];h.xp+=amount;while(h.lv<99&&h.xp>=needXp(h.lv)){h.xp-=needXp(h.lv);h.lv++;h.points+=3;let st=stats(i);actors[i].hp=st.hp;actors[i].mp=st.mp;fx(actors[i].x,actors[i].y,70,HEROES[i].color);logMessage(HEROES[i].name+' 升至 '+h.lv+' 级！获得3点自由属性。');tone(720,.2)}let p=petOf(i);if(p){p.xp+=amount;while(p.lv<99&&p.xp>=petNeed(p.lv)){p.xp-=petNeed(p.lv);p.lv++;logMessage(PETS[p.type].name+' 升至 '+p.lv+' 级，骑乘加成提升。')}}}}
function addPet(type,announce=true){let old=S.pets.find(p=>p.type===type);if(old){old.xp+=petNeed(old.lv);if(old.lv<99){old.xp-=petNeed(old.lv);old.lv++}if(announce)logMessage('重复灵兽化为灵力：'+PETS[type].name+' 升级！');return old}let p={id:type+1,type,lv:1,xp:0};S.pets.push(p);if(S.heroes[S.active].pet===null)S.heroes[S.active].pet=p.id;if(announce)logMessage('获得骑宠 '+PETS[type].name+'！在灵兽面板分配给伙伴。');return p}
function addItem(z,boss=false){let tier=boss?Math.min(3,1+Math.floor(z/2)):Math.random()<.15?Math.min(3,1+Math.floor(z/2)):Math.random()<.5?1:0;let item={id:S.nextItem++,slot:Math.floor(Math.random()*3),tier,power:Math.round(5+z*4+tier*5+rng(0,4))};if(S.bag.length<60){S.bag.push(item);logMessage('获得 '+itemName(item)+'，可在行囊中装备。')}else{S.gold+=item.power*3;logMessage('行囊已满，掉落装备自动换成金币。')}return item}
function enemyDamage(e,amount,source,element,crit=false){if(e.dead||!enemyEligible19(e))return;let target=HEROES[e.element].element,sourceEl=HEROES[element].element;const counter={金:'木',木:'土',土:'水',水:'火',火:'金'};let mul=counter[sourceEl]===target?1.25:1;let dmg=Math.max(1,Math.round(amount*mul));e.hp-=dmg;e.aggro=5;float(e.x,e.y-e.r-5,(crit?'暴击 ':'')+dmg,mul>1?'#e7e789':HEROES[element].color);if(e.hp<=0)kill(e,source)}
function baseKill(e,source){if(e.dead)return;e.dead=true;e.respawn=28;e.wind=null;S.gold+=e.boss?90+e.z*45:8+e.z*4;S.totalKills++;if(!e.boss&&!e.rift&&e.map>=1&&e.map<=5)S.kills[e.z]++;awardXp(e.boss?110+e.z*50:20+e.z*9);fx(e.x,e.y,e.boss?110:35,ZONES[e.z].accent);tone(e.boss?250:510,.1);if(e.boss){bossReward(e.z);return}loot.push({x:e.x,y:e.y,t:2,color:'#dab76d'});if(Math.random()<.24)addItem(e.z);if(Math.random()<.06){S.potions++;logMessage('妖兽掉落了一瓶恢复药剂。')}if(Math.random()<.015)addPet(Math.min(1,e.z));if(!S.prologue&&S.totalKills>=4){S.prologue=true;addPet(0);logMessage('支线完成：初战告捷！获得青背恐龙与40金币。');S.gold+=40;saveGame(false)}refreshBars();}
function bossReward(z){if(S.bosses[z])return;S.bosses[z]=true;addItem(z,true);S.potions+=2;let rescued=-1;for(let i=0;i<5;i++)if(!owned(i)){rescued=i;break}if(rescued>=0){let h=S.heroes[rescued]=createHero23(rescued,true,S,'boss:'+z);let a=actors[rescued];a.x=active().x+45;a.y=active().y+30;a.hp=stats(rescued).hp;a.mp=stats(rescued).mp;}
 if(z===0)addPet(0,false);if(z===1)addPet(2,false);if(z===3)addPet(3,false);if(z===4){addPet(4,false);S.won=true}else S.chapter=z+1;
 for(let i=0;i<5;i++)if(owned(i)){actors[i].hp=stats(i).hp;actors[i].mp=stats(i).mp;actors[i].down=0}
 showDialog(`<div class="kicker">${z===4?'五行归位 · 主线完成':'灵印归位 · 章节完成'}</div><h2 style="margin-top:10px">${ZONES[z].boss}已被击败</h2><p>${ZONES[z].after}</p><div class="row"><div><strong>远征奖励</strong><p>金币 +${90+z*45} · 全队经验 +${110+z*50} · 守护者装备 · 恢复药剂 ×2</p>${rescued>=0?'<p>'+HEROES[rescued].name+' · '+HEROES[rescued].title+' 加入小队（自动跟随战斗）</p>':''}<p>${z===0?'获得青背恐龙':z===1?'获得玄武骑宠':z===3?'获得青龙骑宠':z===4?'获得朱雀骑宠':'下一片区域已解锁'}</p></div></div><p>${z===4?'远征并未结束：仍可探索宝箱、收集坐骑、培养全队。':'下一站：'+ZONES[S.chapter].name+'。'+ZONES[S.chapter].story}</p><div class="actions"><button class="primary" data-close>继续远征 →</button><button id="rewardCamp">回营地整备</button></div>`,'story');$('#rewardCamp').onclick=()=>{closeDialog();returnCamp(true)};logMessage(rescued>=0?HEROES[rescued].name+' 加入了小队！':'五行灵脉已恢复！');saveGame(false);refreshBars();}
function nearestEnemy(a,range,includeDormant=false){let target=null,near=range;for(let e of enemies)if(!e.dead&&(e.z<=S.chapter||S.won)&&(!e.boss||includeDormant||S.kills[e.z]>=ZONES[e.z].need)){let d=dist(a,e);if(d<near){near=d;target=e}}return target}
function baseAttack(a,manual=false){if(a.hp<=0||a.attack>0)return;let st=stats(a.i),e=nearestEnemy(a,st.range+15);if(!e){if(manual)logMessage('没有进入攻击范围的目标，靠近妖兽后再试。');return}a.attack=st.interval;a.face=e.x>=a.x?1:-1;let crit=Math.random()<st.crit;enemyDamage(e,st.atk*(crit?(st.critDamage18||1.8):1),a.i,a.i,crit);effects.push({x:a.x,y:a.y-15,tx:e.x,ty:e.y-e.r/2,color:HEROES[a.i].color,type:st.range>100?'bolt':'slash',t:.18,max:.18,r:st.range});tone(200+a.i*80,.045)}
function heal(a,amount){if(a.hp<=0)return;const st=stats(a.i),v=Math.min(st.hp-a.hp,Math.round(amount));a.hp+=v;if(v>0)float(a.x,a.y-45,'+'+v,'#98e6a9')}
function shield(a,amount,duration=6){if(a.hp<=0)return;a.shield=Math.max(a.shield,amount);a.shieldTime=duration;fx(a.x,a.y,42,'#8fd0dc')}
function baseSkill(i,slot,manual=false){if(menu||!S)return false;const a=actors[i],h=S.heroes[i],st=stats(i),cost=[18,28,52][slot],cd=[5.5,11,28][slot];if(a.hp<=0)return false;if(slot===2&&h.lv<3&&!h.skillsKept10){if(manual)logMessage('终极技能需要角色达到3级。');return false}if(a.cd[slot]>0)return false;if(a.mp<cost){if(manual)logMessage('法力不足，使用恢复药剂 H 或回营地休整。');return false}
 const range=slot===2?(i===0?290:i===4?300:420):slot===0&&(i===0||i===4)?(i===0?135:150):slot===1&&i===3?230:370;const e=nearestEnemy(a,range),support=(i===1&&slot>0)||(i===2&&slot===1)||(i===4&&slot===1);if(!e&&!support){if(manual)logMessage('附近没有可攻击的目标。');return false}a.cd[slot]=cd;a.mp-=cost;let center=e?{x:e.x,y:e.y}:{x:a.x,y:a.y},targets=[];const nearby=(p,r)=>enemies.filter(n=>!n.dead&&dist(n,p)<r&&(n.z<=S.chapter||S.won)&&(!n.boss||S.kills[n.z]>=ZONES[n.z].need));let magic=st.int+st.spell;
 if(i===0){if(slot===0){targets=nearby(a,135);for(let n of targets)enemyDamage(n,st.atk*2.1+magic,i,i)}if(slot===1){let dx=e.x-a.x,dy=e.y-a.y,len=Math.max(1,Math.hypot(dx,dy)),step=Math.max(0,Math.min(len-45,230));a.x=clamp(a.x+dx/len*step,30,WW-30);a.y=clamp(a.y+dy/len*step,30,WH-30);a.inv=.8;enemyDamage(e,st.atk*2.5+magic,i,i)}if(slot===2)for(let n of nearby(a,290))enemyDamage(n,st.atk*5+magic*3,i,i)}
 if(i===1){if(slot===0){enemyDamage(e,st.atk*1.8+magic*2,i,i);e.root=3}if(slot===1)for(let b of actors)if(owned(b.i))heal(b,45+magic*3);if(slot===2){for(let b of actors)if(owned(b.i))heal(b,100+magic*6);for(let n of nearby(a,320)){n.root=4;enemyDamage(n,magic*5+st.atk*2,i,i)}}}
 if(i===2){if(slot===0)for(let n of nearby(center,150)){enemyDamage(n,magic*5+st.atk,i,i);n.slow=4}if(slot===1)for(let b of actors)if(owned(b.i))shield(b,45+magic*3);if(slot===2)for(let n of nearby(center,300)){enemyDamage(n,magic*10,i,i);n.root=2.5;n.slow=5}}
 if(i===3){if(slot===0)for(let n of nearby(center,115)){enemyDamage(n,magic*6+st.atk,i,i);n.burn=4;n.burnPower=magic*.7;n.burnTick=.9}if(slot===1)for(let n of nearby(a,230)){enemyDamage(n,magic*5,i,i);n.burn=4;n.burnPower=magic*.6;n.burnTick=.9}if(slot===2)for(let n of nearby(center,300)){enemyDamage(n,magic*12,i,i);n.burn=5;n.burnPower=magic*.8;n.burnTick=.9}}
 if(i===4){if(slot===0)for(let n of nearby(a,150)){enemyDamage(n,st.str*4+st.atk,i,i);n.root=2}if(slot===1){shield(a,90+st.str*4,8);for(let n of nearby(a,320)){n.taunt=5;n.aggro=5}}if(slot===2){for(let n of nearby(a,300)){enemyDamage(n,st.str*7+magic*2,i,i);n.root=2}for(let b of actors)if(owned(b.i))shield(b,60+st.str*3)}}
 fx(slot===1?a.x:center.x,slot===1?a.y:center.y,slot===2?280:slot===0?110:185,HEROES[i].color,slot===2?'burst':'ring',slot===2?.85:.55);float(a.x,a.y-65,HEROES[i][['q','e','r'][slot]],HEROES[i].color);tone(330+i*90,.16,'triangle');return true}
function baseActorDamage(a,n){if(a.hp<=0||a.inv>0)return;const st=stats(a.i);let dmg=n/(1+.055*st.armor);if(a.shield>0){let blocked=Math.min(dmg,a.shield);a.shield-=blocked;dmg-=blocked}a.hp=Math.max(0,a.hp-dmg);if(dmg>0)float(a.x,a.y-40,'−'+Math.ceil(dmg),'#f8a590');if(a.hp<=0){a.down=22;logMessage(HEROES[a.i].name+' 倒下了，可切换伙伴或回营地。');fx(a.x,a.y,50,'#dd8b7d');if(a.i===S.active){const alive=actors.find(v=>owned(v.i)&&v.hp>0&&(v.map19===undefined||v.map19===currentMap()));if(alive){S.active=alive.i;destination=null}else{S.death++;let loss=Math.floor(S.gold*.1);S.gold-=loss;returnCamp(true);showDialog(`<h2>长老把你们捞了回来</h2><p>“我就知道，药还得多备几瓶。”<br>全队已恢复，损失 ${loss} 金币（10%），角色经验和物品均保留。</p><div class="actions"><button class="primary" data-close>整备后再战</button></div>`,'story')}}}}
function basePotion(){if(!S||menu)return;if(S.potions<=0){logMessage('没有药剂了，去五行百宝阁补充。');return}S.potions--;for(let a of actors)if(owned(a.i)&&a.hp>0){heal(a,stats(a.i).hp*.45);a.mp=Math.min(stats(a.i).mp,a.mp+stats(a.i).mp*.45)}tone(650,.13);logMessage('全队恢复45%生命与法力。');refreshBars();}
function returnCamp(force=false){if(!S)return;if(!force&&enemies.some(e=>!e.dead&&e.aggro>0&&dist(active(),e)<400)){logMessage('战斗中无法回营，脱离敌人后再试。');return}S.position={...CAMP};for(let a of actors)if(owned(a.i)){a.x=CAMP.x+(a.i-2)*35;a.y=CAMP.y+35;a.hp=stats(a.i).hp;a.mp=stats(a.i).mp;a.shield=0;a.down=0;a.guard=0;a.dodge=0;a.slow=0;a.cd=[0,0,0]}for(let e of enemies){e.aggro=0;e.wind=null}destination=null;saveGame(false);logMessage('全队返回青禾营地，生命与法力已恢复。');refreshBars();}
function atCamp(){return dist(active(),CAMP)<260}
function interact(){if(!S||menu)return;const a=active();let npc=NPCS.find(n=>dist(a,n)<100);if(npc){if(npc.kind==='shop')shop();else if(npc.kind==='pets')petsPanel();else storyPanel();return}let chest=CHESTS.findIndex((c,i)=>!S.chests.includes(i)&&dist(a,c)<100);if(chest>=0){let c=CHESTS[chest];if(c.z>S.chapter&&!S.won){logMessage('这里的灵脉尚未解锁，先完成当前章节。');return}S.chests.push(chest);S.gold+=60+c.z*20;S.potions++;addItem(c.z,true);if(c.z===2)addPet(2);if(c.z===3)addPet(3);if(c.z===4)addPet(4);logMessage('打开远古宝箱：金币、药剂与一件珍藏装备！');fx(c.x,c.y,90,'#e7cf83');saveGame(false);refreshBars();return}let shrine=enemies.find(e=>e.boss&&!e.dead&&dist(a,e)<160);if(shrine){logMessage(S.kills[shrine.z]<ZONES[shrine.z].need?'守护者护盾仍在：先击败本区域 '+ZONES[shrine.z].need+' 只妖兽。':'灵脉护盾已破，靠近守护者开始战斗！');return}logMessage('靠近长老、商人、灵兽师或宝箱，按 F 互动。')}
function storyPanel(){const z=ZONES[S.chapter];showDialog(`<div class="kicker">灵脉长老 · 远征手札</div><h2>${S.won?'五行归位':'第'+(S.chapter+1)+'章：'+z.name}</h2><p>${S.won?'长老总算能安心喝茶。五位战士还在争论谁的坐骑最拉风，而远方仍有未开启的宝箱等待探索。':z.story}</p><div class="row"><div><strong>${S.won?'主线完成':'当前目标'}</strong><p>${S.won?'继续培养角色与骑宠，探索全部5个远古宝箱。':'击败该区域 '+z.need+' 只妖兽，破除守护者护盾，再击败 '+z.boss+'。当前 '+S.kills[S.chapter]+' / '+z.need}</p></div></div><p>每位首领都会提供金币、经验和装备，前四位首领还会唤醒一名伙伴。<br>支线「初战告捷」：累计击败4只妖兽，获得恐龙坐骑。${S.prologue?'✓ 已完成':'当前 '+S.totalKills+' / 4'}</p><div class="actions"><button class="primary" data-close>继续冒险</button><button id="storyHelp">查看玩法</button></div>`,'story');$('#storyHelp').onclick=help}
function panelHead(title){return `<div class="kicker">远征整备 / 游戏已暂停</div><h2 style="margin-top:8px">${title}</h2><div class="actions" style="margin:0 0 12px"><button data-close>返回游戏 Esc</button></div>`}
function talentPanel(){if(!S)return;let i=S.active,h=S.heroes[i],st=stats(i);showDialog(panelHead('战士天赋 · '+HEROES[i].name)+`<p>${HEROES[i].desc} · Lv.${h.lv} · 可分配 <strong>${h.points}</strong> 点<br>每次升级按职业自动成长，并获得3点自由属性。加点后立即生效。</p>`+['力量','智力','敏捷'].map((n,k)=>`<div class="row"><div><strong>${n} ${[st.str,st.int,st.agi][k]}</strong><p>${['每点增加11生命；土系额外提升普攻与力量技能。','每点增加5法力；提升法术、治疗、护盾与法力回复。','提升攻速、暴击、移动速度与护甲；金木系提升普攻。'][k]}</p></div><button data-stat="${k}" ${h.points<=0?'disabled':''}>分配 +1</button></div>`).join('')+`<p class="muted">伤害减免 = 护甲 ×0.055 /（1 + 护甲 ×0.055）。暴击伤害180%，暴击率上限45%。<br>克制关系固定：金→木→土→水→火→金，克制伤害增加25%。属性效果为原创平衡设计。</p><div class="actions"><button id="resetTalent">重置自由加点 · 50金币</button></div>`);$('#dialog').querySelectorAll('[data-stat]').forEach(b=>b.onclick=()=>{if(h.points<=0)return;let old=stats(i).hp;h.points--;h.bonus[+b.dataset.stat]++;actors[i].hp+=stats(i).hp-old;talentPanel();refreshBars();saveGame(false)});$('#resetTalent').onclick=()=>{if(S.gold<50){logMessage('金币不足，重置需要50金币。');return}if(!h.bonus.some(Boolean))return;S.gold-=50;h.points+=h.bonus.reduce((a,b)=>a+b,0);h.bonus=[0,0,0];actors[i].hp=Math.min(actors[i].hp,stats(i).hp);actors[i].mp=Math.min(actors[i].mp,stats(i).mp);talentPanel();refreshBars();saveGame(false)}}
function equipItem(id,i){let idx=S.bag.findIndex(v=>v.id===id);if(idx<0||!owned(i))return;let item=S.bag[idx],h=S.heroes[i],old=h.gear[item.slot];S.bag.splice(idx,1);h.gear[item.slot]=item;if(old)S.bag.push(old);actors[i].hp=Math.min(actors[i].hp,stats(i).hp);saveGame(false);refreshBars()}
function bagPanel(){if(!S)return;let i=S.active,h=S.heroes[i];showDialog(panelHead('装备行囊 · '+HEROES[i].name)+`<p>金币 ${S.gold} · 行囊 ${S.bag.length} / 60 · 药剂 ${S.potions}<br>装备分别影响攻击、护甲生命和法术强度。先切换角色，再分配装备。</p><h3>当前装备</h3>`+['武器','护甲','法器'].map((n,k)=>`<div class="row"><div><strong>${n}：${h.gear[k]?itemName(h.gear[k]):'未装备'}</strong><p>${['武器每点提供1攻击','护甲每点提供0.45护甲与5生命','法器每点增加1法术强度，强化技能治疗与伤害'][k]}</p></div>${h.gear[k]?'<button data-unequip="'+k+'">卸下</button>':''}</div>`).join('')+`<h3>战利品</h3>${S.bag.length?S.bag.map(it=>`<div class="row"><div><strong class="${it.tier>=2?'equip':''}">${itemName(it)}</strong><p>${['攻击 +','护甲 +'+(it.power*.45).toFixed(1)+' / 生命 +','法强 +'][it.slot]}${it.slot===1?it.power*5:it.power}</p></div><div><button data-equip="${it.id}">装备</button> <button data-sell="${it.id}">售 ${it.power*3}金</button></div></div>`).join(''):'<p>妖兽、首领和远古宝箱都会掉落装备。</p>'}<div class="actions"><button id="autoEquip">自动装备当前角色</button></div>`);$('#dialog').querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{equipItem(+b.dataset.equip,i);bagPanel()});$('#dialog').querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>{let idx=S.bag.findIndex(it=>it.id===+b.dataset.sell);if(idx<0)return;S.gold+=S.bag[idx].power*3;S.bag.splice(idx,1);saveGame(false);refreshBars();bagPanel()});$('#dialog').querySelectorAll('[data-unequip]').forEach(b=>b.onclick=()=>{let k=+b.dataset.unequip;if(S.bag.length>=60){logMessage('行囊已满，请先出售装备。');return}S.bag.push(h.gear[k]);h.gear[k]=null;actors[i].hp=Math.min(actors[i].hp,stats(i).hp);saveGame(false);refreshBars();bagPanel()});$('#autoEquip').onclick=()=>{for(let k=0;k<3;k++){let best=S.bag.filter(it=>it.slot===k).sort((a,b)=>b.power-a.power)[0];if(best&&best.power>(h.gear[k]?.power||0))equipItem(best.id,i)}bagPanel()}}
function petsPanel(){if(!S)return;showDialog(panelHead('灵兽契约 · 骑宠图鉴')+`<p>每位战士可骑乘一只灵兽，每只灵兽仅能绑定一位战士。骑宠随全队战斗获得经验，每次升级强化18%基础加成，并提高移动速度。已拥有的重复灵兽转化为1级成长。</p>`+PETS.map((p,type)=>{let pet=S.pets.find(v=>v.type===type),owner=pet?S.heroes.findIndex(h=>h.pet===pet.id):-1;return `<div class="row"><div><strong>${p.icon} ${p.name}${pet?' · Lv.'+pet.lv:' · 未发现'}</strong><p>${p.bonus}<br>${pet?'经验 '+pet.xp+' / '+petNeed(pet.lv)+' · '+(owner>=0?'骑乘者：'+HEROES[owner].name:'待分配'):p.desc}</p></div>${pet?`<select data-pet="${pet.id}" aria-label="分配${p.name}"><option value="-1">暂不骑乘</option>${HEROES.map((d,i)=>owned(i)?`<option value="${i}" ${owner===i?'selected':''}>${d.name}</option>`:'').join('')}</select>`:'<span class="pill">待收集</span>'}</div>`}).join('')+`<p class="muted">获取路线：恐龙—击败4只妖兽；白虎—商店购买；玄武—第二章首领/第三章宝箱；青龙—第四章首领/宝箱；朱雀—终章首领/宝箱。普通妖兽有1.5%概率提供恐龙或白虎灵兽。</p>`);$('#dialog').querySelectorAll('[data-pet]').forEach(sel=>sel.onchange=()=>{let id=+sel.dataset.pet,i=+sel.value;for(let h of S.heroes)if(h.pet===id)h.pet=null;if(i>=0)S.heroes[i].pet=id;for(let a of actors){a.hp=Math.min(a.hp,stats(a.i).hp);a.mp=Math.min(a.mp,stats(a.i).mp)}saveGame(false);refreshBars();petsPanel()})}
function buy(kind){if(!atCamp()){logMessage('商人只在营地营业，请先脱离战斗并回营。');return false}let cost=kind==='potion'?25:kind==='tiger'?180:kind==='rest'?0:100+S.chapter*45;if(S.gold<cost){logMessage('金币不足，需要 '+cost+' 金币。');return false}S.gold-=cost;if(kind==='potion')S.potions+=2;else if(kind==='tiger')addPet(1);else if(kind==='rest'){for(let a of actors)if(owned(a.i)){a.hp=stats(a.i).hp;a.mp=stats(a.i).mp;a.down=0}}else addItem(S.chapter,true);saveGame(false);refreshBars();return true}
function shop(){if(!S)return;const camp=atCamp(),disabled=camp?'':'disabled';showDialog(panelHead('百宝商人 · 五行百宝阁')+`<p>“世界可以等一等，先把装备和药买齐。”<br>当前金币 <strong>${S.gold}</strong> · ${camp?'你正在营地，可以交易。':'只有回到青禾营地才能交易。脱离战斗后可点击右上角「回营」。'}</p><div class="row"><div><strong>恢复药剂 ×2</strong><p>每瓶恢复所有存活队员45%生命与法力，快捷键 H。</p></div><button data-buy="potion" ${disabled}>25 金币</button></div><div class="row"><div><strong>🐅 霜牙白虎契约</strong><p>高机动攻击坐骑。重复购买可使已拥有白虎升级。</p></div><button data-buy="tiger" ${disabled}>180 金币</button></div><div class="row"><div><strong>灵脉装备箱</strong><p>随机获得当前章节一件首领品质装备。</p></div><button data-buy="gear" ${disabled}>${100+S.chapter*45} 金币</button></div><div class="row"><div><strong>营地休整</strong><p>全队恢复生命与法力，唤醒倒下的伙伴。</p></div><button data-buy="rest" ${disabled}>免费恢复</button></div>`);$('#dialog').querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{if(buy(b.dataset.buy))shop()})}
function baseExportSave(data=S){if(!data)return;let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='五行战记-远征存档.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function importSave(){let input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;input.id='saveImport17';document.querySelector('#saveImport17')?.remove();document.body.appendChild(input);input.onchange=async()=>{try{if(!input.files[0]||input.files[0].size>8*1024*1024)throw Error();let data=JSON.parse(await input.files[0].text());if(!validateSave(data))throw Error();showDialog('<h2>载入这份远征存档？</h2><p>载入后会替换当前浏览器的自动存档。可以先导出当前进度。</p><div class="actions"><button id="backupCurrent">导出当前存档</button><button id="confirmImport" class="primary">确认载入</button><button id="cancelImport">返回</button></div>','import');$('#backupCurrent').onclick=()=>exportSave(S||readSave());$('#confirmImport').onclick=()=>begin(data);$('#cancelImport').onclick=()=>S?pausePanel():intro()}catch{showDialog('<h2>无法读取存档</h2><p>请选择本游戏导出的完整 JSON 存档文件。</p><button id="importBack">返回</button>','import');$('#importBack').onclick=()=>S?pausePanel():intro()}};input.click()}
function pausePanel(){if(!S)return;showDialog(panelHead('远征暂停')+`<p>进度会自动保存。换浏览器或换设备前，请导出存档备份；这里只保存单机进度，不进行账号同步。</p><div class="actions"><button id="manualSave" class="primary">保存进度</button><button id="export">导出存档</button><button id="import">导入存档</button><button id="backTitle">返回标题</button></div><p class="save-status" id="saveStatus">${notice||'当前进度已保留在游戏中'}</p>`,'pause');$('#manualSave').onclick=()=>{saveGame();$('#saveStatus').textContent=notice};$('#export').onclick=()=>{saveGame(false);exportSave()};$('#import').onclick=importSave;$('#backTitle').onclick=()=>{saveGame(false);intro()}}
function help(){let was=!!S;showDialog((was?panelHead('五行远征 · 玩法指南'):'<h2>五行远征 · 玩法指南</h2>')+`<div class="grid2"><div><h3>01 · 操控与战斗</h3><p>WASD / 方向键移动，或点击地面自动走过去。<br>J 普攻，默认会自动攻击射程内敌人。<br>Q / E 主动技能，R 终极技能（3级解锁）。<br>H 使用全队恢复药剂，F 与附近目标互动。<br>1—5 切换已招募且存活的战士。B 打开行囊。<br>手机使用画面下方方向与技能按钮。点击小地图导航。</p><h3>02 · 属性与成长</h3><p>击败妖兽，全队已加入成员分享完整经验。<br>升级自动增加职业属性，同时获得3点自由加点。<br>力量加生命，智力加法力与技能强度，敏捷加攻速、暴击、护甲和移动。主属性额外提升普攻。<br>金克木、木克土、土克水、水克火、火克金，克制伤害+25%。</p><h3>03 · 同行伙伴</h3><p>击败前四章首领，各唤醒一名未加入的战士。伙伴跟随、自动攻击并使用基础技能与支援技能。<br>伙伴倒下后22秒在身边恢复；全队倒下会被长老救回营地，扣除10%金币。</p></div><div><h3>04 · 五章剧情</h3><p>按小地图区域顺序探索。每区先完成杀怪数量，破除祭坛守护者护盾，再挑战首领。未解锁区域会提示当前任务。<br>首领出招前会出现红色圆圈，走出预警区域躲避攻击。伙伴也会尝试躲避。</p><h3>05 · 装备与骑宠</h3><p>野怪、首领与宝箱掉落装备，金币自动拾取。头盔、首饰、护甲、武器、防具、靴子共6个独立装备槽，打开行囊穿戴或出售。<br>击败4只妖兽送恐龙；商店可以买白虎；后续剧情与宝箱可获得玄武、青龙、朱雀。<br>灵兽面板可给每位战士分配不同坐骑，骑宠随主人获得经验并升级。</p><h3>06 · 整备与存档</h3><p>脱离敌人后点击「回营」恢复全队，商店补给和装备箱只在营地交易。<br>面板打开时战斗暂停。每15秒、重要奖励与加点后自动保存；导出存档可以换设备继续。</p></div></div><div class="actions"><button id="helpBack" class="primary">${was?'返回游戏':'返回标题'}</button></div>`,'help');$('#helpBack').onclick=()=>was?closeDialog():intro()}

function baseMove(a,dx,dy,speed,dt){let len=Math.hypot(dx,dy);if(len<1e-4)return;let x=a.x+dx/len*speed*dt,y=a.y+dy/len*speed*dt;let locked=ZONES.findIndex((z,i)=>i>S.chapter&&!S.won&&Math.hypot(x-z.x,y-z.y)<375);if(locked>=0){if(a.i===S.active&&time>(move.warn||0)){move.warn=time+3;logMessage('灵脉屏障：请先完成 '+ZONES[S.chapter].name+' 的主线。')}destination=null;return}a.x=clamp(x,70,WW-70);a.y=clamp(y,145,WH-35);if(Math.abs(dx)>.1)a.face=dx>0?1:-1;a.walk+=dt*speed*.045}
function targetActor(e){let candidates=actors.filter(a=>owned(a.i)&&a.hp>0);if(e.taunt>0&&owned(4)&&actors[4].hp>0&&dist(e,actors[4])<450)return actors[4];return candidates.sort((a,b)=>dist(e,a)-dist(e,b))[0]}
function baseUpdate(dt){if(!S||menu)return;time+=dt;S.played+=dt;let a=active(),st=stats(S.active);let mx=(keys.has('KeyD')||keys.has('ArrowRight')?1:0)-(keys.has('KeyA')||keys.has('ArrowLeft')?1:0),my=(keys.has('KeyS')||keys.has('ArrowDown')?1:0)-(keys.has('KeyW')||keys.has('ArrowUp')?1:0);if(mx||my){destination=null;move(a,mx,my,st.speed,dt)}else if(destination){let dd=dist(a,destination);if(dd<8)destination=null;else move(a,destination.x-a.x,destination.y-a.y,st.speed,dt)}
 for(let b of actors){if(!owned(b.i))continue;const s=stats(b.i);if(b.hp<=0){b.down-=dt;if(b.down<=0){b.hp=s.hp*.5;b.mp=s.mp*.5;b.x=a.x+rng(-35,35);b.y=a.y+rng(-35,35);b.inv=2;logMessage(HEROES[b.i].name+' 重新站了起来。')}continue}b.inv=Math.max(0,b.inv-dt);b.attack=Math.max(0,b.attack-dt);b.cd=b.cd.map(n=>Math.max(0,n-dt));b.hp=Math.min(s.hp,b.hp+dt*(atCamp()?s.hp*.12:.4+s.str*.012));b.mp=Math.min(s.mp,b.mp+dt*(atCamp()?s.mp*.15:1.4+s.int*.085));b.shieldTime=Math.max(0,b.shieldTime-dt);if(b.shieldTime===0)b.shield=0;
 if(b.i===S.active){if($('#autoAttack').checked||keys.has('KeyJ'))attack(b);continue}
 let threat=nearestEnemy(b,410),hazard=enemies.find(e=>e.wind&&dist(b,e.wind)<e.wind.r+35);if(hazard){let dx=b.x-hazard.wind.x,dy=b.y-hazard.wind.y;if(Math.hypot(dx,dy)<3)dx=1;move(b,dx,dy,s.speed,dt)}else if(threat&&dist(a,threat)<450){let dd=dist(b,threat);if(dd>s.range*.85)move(b,threat.x-b.x,threat.y-b.y,s.speed,dt)}else{let tx=a.x+Math.cos(b.i*2.5)*68,ty=a.y+Math.sin(b.i*2.5)*68;if(Math.hypot(tx-b.x,ty-b.y)>40)move(b,tx-b.x,ty-b.y,s.speed,dt);if(dist(a,b)>650){b.x=a.x+rng(-45,45);b.y=a.y+rng(-45,45)}}
 attack(b);if(threat){if(dist(b,threat)<(b.i===0||b.i===4?130:340))skill(b.i,0);if(b.i===0&&dist(b,threat)>100||b.i===3&&dist(b,threat)<210||b.i===4&&b.hp<s.hp*.7)skill(b.i,1)}if(b.i===1&&actors.some(c=>owned(c.i)&&c.hp>0&&c.hp<stats(c.i).hp*.75))skill(b.i,1);if(b.i===2&&threat&&actors.some(c=>owned(c.i)&&c.hp>0&&c.hp<stats(c.i).hp*.8))skill(b.i,1);
 }
 if(menu)return;updateEnemies(dt);
 for(let e of effects)e.t-=dt;effects=effects.filter(e=>e.t>0);for(let n of numbers){n.t-=dt;n.y-=dt*27}numbers=numbers.filter(n=>n.t>0);for(let l of loot)l.t-=dt;loot=loot.filter(l=>l.t>0);let desiredX=clamp(active().x-VW*.5,0,WW-VW),desiredY=clamp(active().y-VH*.5,0,WH-VH);cam.x+=(desiredX-cam.x)*Math.min(1,dt*6);cam.y+=(desiredY-cam.y)*Math.min(1,dt*6);
 hudTime-=dt;if(hudTime<=0){hudTime=.18;refreshBars();let zone=ZONES.find((z,i)=>dist(a,z)<390&&(i<=S.chapter||S.won));$('#zoneName').innerHTML=zone?zone.name+' <small>'+HEROES[zone.element].element+'属性妖兽区域</small>':'青禾古道 <small>'+ (atCamp()?'营地 · 安全区':'跟随小地图探索五行祭坛')+'</small>';let chest=CHESTS.find((c,i)=>!S.chests.includes(i)&&dist(a,c)<95),npc=NPCS.find(n=>dist(a,n)<95);$('#hint').textContent=npc?'按 F 与'+npc.name+'交谈':chest?'按 F 开启远古宝箱':atCamp()?'长老、商人与灵兽师就在身边。准备好后向东进入林地。':S.won?'五行灵脉已修复，探索宝箱并继续培养你的队伍。':'目标：'+ZONES[S.chapter].name+' · '+Math.min(S.kills[S.chapter],ZONES[S.chapter].need)+'/'+ZONES[S.chapter].need+' 妖兽 → 挑战守护者';let boss=enemies.find(e=>e.boss&&!e.dead&&dist(active(),e)<450&&e.z<=S.chapter);$('#bossHud').classList.toggle('hidden',!boss);if(boss)$('#bossHud').innerHTML=ZONES[boss.z].boss+(S.kills[boss.z]<ZONES[boss.z].need?' · 灵脉护盾':'')+'<div class="bar"><b style="width:'+clamp(boss.hp/boss.max*100,0,100)+'%"></b></div>';if(log.some(v=>time-v.t>10)){log=log.filter(v=>time-v.t<10);$('#combatLog').replaceChildren(...log.map(v=>{let el=document.createElement('div');el.textContent=v.text;return el}))}}
 if(time-lastAutoSave>15){lastAutoSave=time;saveGame(false)}}

// 轻量手绘风格画布渲染：地图、角色、灵兽均由本地矢量笔触组成。
function ellipse(x,y,rx,ry,color,rot=0){g.fillStyle=color;g.beginPath();g.ellipse(x,y,rx,ry,rot,0,Math.PI*2);g.fill()}
function rr(x,y,w,h,r,color){g.fillStyle=color;g.beginPath();g.roundRect(x,y,w,h,r);g.fill()}
function line(x1,y1,x2,y2,color,width=2){g.strokeStyle=color;g.lineWidth=width;g.lineCap='round';g.beginPath();g.moveTo(x1,y1);g.lineTo(x2,y2);g.stroke()}
function poly(points,color){g.fillStyle=color;g.beginPath();points.forEach((p,i)=>i?g.lineTo(...p):g.moveTo(...p));g.closePath();g.fill()}
function label(text,x,y,color='#dbe2ca',size=12){g.font=`${size}px "Microsoft YaHei",system-ui`;g.textAlign='center';g.fillStyle='#071816c0';g.fillText(text,x+1,y+1);g.fillStyle=color;g.fillText(text,x,y)}
function circle(x,y,r,color,width=2){g.strokeStyle=color;g.lineWidth=width;g.beginPath();g.arc(x,y,r,0,Math.PI*2);g.stroke()}
function tree(x,y,scale=1,color='#345b48'){g.save();g.translate(x,y);g.scale(scale,scale);ellipse(9,13,36,12,'#07171265');rr(-6,-35,12,48,3,'#4a4536');poly([[-39,-25],[0,-113],[39,-25]],'#254735');poly([[-35,-44],[0,-126],[35,-44]],color);poly([[-27,-70],[0,-137],[27,-70]],'#487052');line(-3,-96,-14,-65,'#71936a66',2);g.restore()}
