const decor=Array.from({length:420},(_,i)=>{let n=Math.sin(i*731.3+1)*43758.54,m=Math.sin(i*249.7+2)*19834.41;return {x:(n-Math.floor(n))*WW,y:(m-Math.floor(m))*WH,type:i%7,scale:.65+(i%5)*.13}});
function drawMap(){g.fillStyle='#29463a';g.fillRect(0,0,WW,WH);for(let z of ZONES){let gradient=g.createRadialGradient(z.x,z.y,60,z.x,z.y,620);gradient.addColorStop(0,z.color);gradient.addColorStop(.67,z.color);gradient.addColorStop(1,'#29463a00');g.fillStyle=gradient;g.fillRect(z.x-620,z.y-620,1240,1240)}
 // 蜿蜒道路连接营地与五行祭坛。
 g.strokeStyle='#aa98652b';g.lineWidth=48;g.lineCap='round';g.beginPath();g.moveTo(CAMP.x,CAMP.y);for(let z of ZONES)g.lineTo(z.x,z.y);g.stroke();g.lineWidth=28;g.strokeStyle='#b9a77813';g.stroke();
 for(let i=0;i<180;i++){let x=(i*137+55)%WW,y=(i*293+70)%WH;if(x<cam.x-50||x>cam.x+VW+50||y<cam.y-50||y>cam.y+VH+50)continue;ellipse(x,y,2,1,'#e8de9a22');line(x-4,y+6,x-2,y-2,'#9cab7233',1);line(x,y+7,x+3,y+1,'#9cab7233',1)}for(let z of ZONES){if(z.element===2){for(let i=0;i<6;i++){ellipse(z.x+150+Math.cos(i)*150,z.y+120+Math.sin(i)*120,60,24,'#78b5c918');line(z.x+120+i*26,z.y+100+i*30,z.x+170+i*26,z.y+100+i*30,'#9fcee222',2)}}if(z.element===3)for(let i=0;i<8;i++){let x=z.x+Math.cos(i*2)*230,y=z.y+Math.sin(i*2)*220;line(x,y,x+30,y+20,'#d7955b44',3);line(x+30,y+20,x+15,y+40,'#d7955b44',2)}}
 drawCamp();for(let [i,z]of ZONES.entries())shrine(z,i);for(let [i,c]of CHESTS.entries()){if(c.x<cam.x-60||c.x>cam.x+VW+60||c.y<cam.y-60||c.y>cam.y+VH+60)continue;ellipse(c.x,c.y+12,26,8,'#041b1888');rr(c.x-22,c.y-17,44,29,4,S?.chests.includes(i)?'#545c49':'#a98b52');rr(c.x-22,c.y-20,44,14,5,'#c0a36a');line(c.x-13,c.y-17,c.x-13,c.y+10,'#68674b',4);line(c.x+13,c.y-17,c.x+13,c.y+10,'#68674b',4);rr(c.x-4,c.y-5,8,11,2,'#e2c87f');if(!S?.chests.includes(i)){circle(c.x,c.y-2,32,'#d7c58244',1);label('宝箱',c.x,c.y-36,'#ddca94',10)}}}
function baseDraw(){g.clearRect(0,0,VW,VH);if(!S){cam={x:0,y:0}}g.save();g.translate(-cam.x,-cam.y);drawMap();
 const things=[];for(let d of decor){if(d.x<cam.x-100||d.x>cam.x+VW+100||d.y<cam.y-40||d.y>cam.y+VH+160)continue;let avoid=[CAMP,...ZONES,...CHESTS,...NPCS].some(z=>dist(d,z)<(z===CAMP?250:105));if(avoid)continue;things.push({y:d.y,draw:()=>{if(d.type<3){const fade=S&&actors.some(a=>owned(a.i)&&a.hp>0&&Math.abs(a.x-d.x)<55*d.scale&&a.y>d.y-140*d.scale&&a.y<d.y+12);g.globalAlpha=fade?.3:1;tree(d.x,d.y,d.scale);g.globalAlpha=1}else if(d.type<5)rock(d.x,d.y,d.scale*.6);else{ellipse(d.x,d.y,9,3,'#152f2580');rr(d.x-2,d.y-10,4,10,1,'#b8b38a');ellipse(d.x,d.y-10,9,5,d.type===5?'#be8876':'#8aa586')}}})}for(let e of enemies)if((!e.dead||e.deathT>0)&&e.x>cam.x-140&&e.x<cam.x+VW+80&&e.y>cam.y-20&&e.y<cam.y+VH+120)things.push({y:e.y,draw:()=>drawEnemy(e)});for(let a of actors)if(S&&owned(a.i))things.push({y:a.y,draw:()=>drawHero(a)});things.sort((a,b)=>a.y-b.y);for(let v of things)v.draw();
 for(let e of effects){let progress=1-e.t/e.max;g.globalAlpha=Math.min(1,e.t*4);if(e.type==='bolt'){line(e.x,e.y,e.tx,e.ty,e.color,3);ellipse(e.tx,e.ty,6,6,e.color)}else if(e.type==='slash'){g.strokeStyle=e.color;g.lineWidth=5;g.beginPath();g.arc(e.x,e.y,35+progress*25,-1.5,.8);g.stroke()}else{circle(e.x,e.y,e.r*(.3+progress*.7),e.color,Math.max(1,6*(1-progress)));if(e.type==='burst'){for(let i=0;i<12;i++){let ang=i*Math.PI/6;line(e.x+Math.cos(ang)*e.r*.2,e.y+Math.sin(ang)*e.r*.2,e.x+Math.cos(ang)*e.r*progress,e.y+Math.sin(ang)*e.r*progress,e.color,3)}}}g.globalAlpha=1}for(let l of loot){ellipse(l.x,l.y-l.t*15,5,8,'#e4c478')}for(let n of numbers){g.globalAlpha=Math.min(1,n.t*2);label(n.text,n.x,n.y,n.color,14);g.globalAlpha=1}if(destination){circle(destination.x,destination.y,12+Math.sin(time*6)*2,'#e4d699',1);line(destination.x-7,destination.y,destination.x+7,destination.y,'#e4d699',1)}g.restore();
 let vignette=g.createRadialGradient(VW*.5,VH*.45,180,VW*.5,VH*.5,760);vignette.addColorStop(0,'#081a1800');vignette.addColorStop(1,'#081a18aa');g.fillStyle=vignette;g.fillRect(0,0,VW,VH);drawMini()}
function drawMini(){mg.clearRect(0,0,190,120);mg.fillStyle='#102b27';mg.fillRect(0,0,190,120);let sx=190/WW,sy=120/WH;mg.lineWidth=7;mg.strokeStyle='#7d805133';mg.beginPath();mg.moveTo(CAMP.x*sx,CAMP.y*sy);for(let z of ZONES)mg.lineTo(z.x*sx,z.y*sy);mg.stroke();for(let [i,z]of ZONES.entries()){mg.fillStyle=S?.bosses[i]?'#a1d7a5':S&&i>S.chapter?'#4e5e56':z.accent;mg.beginPath();mg.arc(z.x*sx,z.y*sy,12,0,Math.PI*2);mg.fill();mg.fillStyle='#1e3432';mg.font='10px sans-serif';mg.textAlign='center';mg.fillText(i+1,z.x*sx,z.y*sy+3)}mg.fillStyle='#d5c591';mg.fillRect(CAMP.x*sx-4,CAMP.y*sy-4,8,8);if(S){for(let a of actors)if(owned(a.i)&&a.hp>0){mg.fillStyle=a.i===S.active?'#ffffff':HEROES[a.i].color;mg.beginPath();mg.arc(a.x*sx,a.y*sy,a.i===S.active?3:2,0,7);mg.fill()}mg.strokeStyle='#e9e2b66a';mg.lineWidth=1;mg.strokeRect(cam.x*sx,cam.y*sy,VW*sx,VH*sy)}}

// 输入与应用生命周期。
window.addEventListener('keydown',e=>{if(e.target instanceof HTMLInputElement||e.target instanceof HTMLSelectElement)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.repeat)return;if(e.code==='KeyP'){if(menu==='start')return;if(menu)closeDialog();else pausePanel();return}if(!S||menu)return;keys.add(e.code);if(/^Digit[1-5]$/.test(e.code))switchHero(+e.code.slice(-1)-1);if(e.code==='KeyQ')skill(S.active,0,true);if(e.code==='KeyE')skill(S.active,1,true);if(e.code==='KeyR')skill(S.active,2,true);if(e.code==='KeyH')potion();if(e.code==='KeyF')interact();if(e.code==='KeyB')bagPanel();if(e.code==='KeyJ')attack(active(),true)});window.addEventListener('keyup',e=>keys.delete(e.code));window.addEventListener('blur',()=>{keys.clear();if(S&&!menu)pausePanel()});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();saveGame(false);if(S&&!menu)pausePanel()}});window.addEventListener('beforeunload',()=>saveGame(false));
