 const key=p=>p.y*cols+p.x,open=[{...start,cost:0,h:Math.abs(start.x-goal.x)+Math.abs(start.y-goal.y)}],came=new Map(),costs=new Map([[key(start),0]]);let finish=null,limit=0;
 while(open.length&&limit++<3500){open.sort((a,b)=>(a.cost+a.h)-(b.cost+b.h));const n=open.shift();if(n.x===goal.x&&n.y===goal.y){finish=n;break}for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const p={x:n.x+dx,y:n.y+dy};if(!walkable(p.x*size+size/2,p.y*size+size/2,25))continue;const id=key(p),cost=n.cost+1;if(cost>=(costs.get(id)??Infinity))continue;costs.set(id,cost);came.set(id,n);open.push({...p,cost,h:Math.abs(p.x-goal.x)+Math.abs(p.y-goal.y)})}}
