const v4Refresh=refreshBars;refreshBars=function(){v4Refresh();if(!S)return;const m=MAPS[currentMap()],h=S.heroes[S.active];$('#zoneName').innerHTML=m.name+' <small>'+(atCamp()?'入口安全区':m.desc)+'</small>';$('#chapterLabel').textContent='诸界 '+currentMap()+'/6 · '+m.name;$('#objective').textContent=currentMap()===0?'整备小队，通过传送门进入独立地图':currentMap()===6?'挑战高等级裂隙守卫，收集装备与经验':S.bosses[currentMap()-1]?'守护者已击败，首领会按冷却时间刷新':`清理 ${Math.min(S.kills[currentMap()-1],ZONES[currentMap()-1].need)} / ${ZONES[currentMap()-1].need} 妖兽，解除首领屏障`;$('#heroDetail').innerHTML+=`<br><span class="job-label">${h.job>=0?CAREERS[S.active][h.job]:'100级可转职'} · 觉醒技 T ${h.ascensionCd>0?Math.ceil(h.ascensionCd)+'s':''}</span>`;const boss=enemies.find(e=>e.map===currentMap()&&e.boss&&!e.dead&&dist(active(),e)<540);$('#bossHud').classList.toggle('hidden',!boss);if(boss)$('#bossHud').innerHTML=(boss.rift?'星渊守门人':ZONES[boss.z].boss)+` <small>Lv.${boss.level} · 阶段 ${boss.phase}/3</small><div class="bar"><b style="width:${clamp(boss.hp/boss.max*100,0,100)}%"></b></div>`;refreshOrderBar()};
