// Every acquired pet occupies one inventory slot. Riding is an explicit assignment.
addPet=function(type,announce=true){if(!PETS[type]||S.pets.length>=100){if(announce)logMessage('灵兽包裹已满（100只）。');return null}const p={id:Math.max(100,...S.pets.map(p=>p.id))+1,type,lv:1,xp:0};S.pets.push(p);if(announce)logMessage('获得 '+PETS[type].name+'，已收入灵兽包裹。');return p};
function assignPet(id,hero){const pet=S.pets.find(p=>p.id===id);if(!pet||!Number.isInteger(hero)||hero< -1||hero>4||hero>=0&&!owned(hero))return false;for(const h of S.heroes)if(h.pet===id)h.pet=null;if(hero>=0)S.heroes[hero].pet=id;for(const a of actors){a.hp=Math.min(a.hp,stats(a.i).hp);a.mp=Math.min(a.mp,stats(a.i).mp)}saveGame(false);refreshBars();return true}
function fusionOdds(a,b,i=S.active){const luck=stats(i).luck,stars=Math.min(a.fusion?.stars||0,b.fusion?.stars||0);return {luck,success:Math.min(.95,.45+luck*.006+stars*.025),rare:Math.min(.5,.08+luck*.004)}}
function fusionPool(a,b){const preferred=fusionResult(a,b);return [preferred,12,13,14]}
function rollFusion(a,b,rare){if(rare){const pool=a.type===3||b.type===3||a.type===4||b.type===4?[15,18,17,16,15,18]:[15,16,17,18];return pool[Math.floor(Math.random()*pool.length)]}const pool=fusionPool(a,b);return pool[Math.floor(Math.random()*pool.length)]}
fusePets=function(idA,idB){const a=S.pets.find(p=>p.id===idA),b=S.pets.find(p=>p.id===idB);if(!a||!b||a===b||a.type===b.type||a.lv<10||b.lv<10||S.gold<250)return null;const odds=fusionOdds(a,b);S.gold-=250;const success=Math.random()<odds.success;let result=null;
 if(success){const rare=Math.random()<odds.rare,type=rollFusion(a,b,rare);result={id:Math.max(100,...S.pets.map(p=>p.id))+1,type,lv:Math.floor((a.lv+b.lv)/2),xp:0,fusion:{parents:[a.type,b.type],stars:Math.min(3,Math.max(a.fusion?.stars||0,b.fusion?.stars||0)+1)}};const ride=S.heroes[S.active].pet;for(const h of S.heroes)if([idA,idB].includes(h.pet))h.pet=null;S.pets=S.pets.filter(p=>![idA,idB].includes(p.id));S.pets.push(result);if([idA,idB].includes(ride))S.heroes[S.active].pet=result.id;logMessage('合体成功：'+PETS[type].name+(type>=15?' · 稀有变异！':'！'))}
 else{for(const h of S.heroes)if(h.pet===idB)h.pet=null;S.pets=S.pets.filter(p=>p.id!==idB);a.lv=Math.max(1,a.lv-1);a.xp=0;logMessage('合体失败：材料二消散，材料一保留并下降1级。')}
 for(const actor of actors){actor.hp=Math.min(actor.hp,stats(actor.i).hp);actor.mp=Math.min(actor.mp,stats(actor.i).mp)}saveGame(false);refreshBars();return {success,pet:result,odds};
};
const petStyleBeforeV6=petCardStyle;petCardStyle=function(type){const mapped=PETS[type]?.art??type;return petStyleBeforeV6(mapped)+(type>=15?';filter:hue-rotate('+(type-14)*32+'deg) saturate(1.25)':'')};
function petPurchase(type){const cost=150+type*115;if(!Number.isInteger(type)||type<0||type>=12||!atCamp()||S.gold<cost||S.pets.length>=100)return false;if(type>4&&S.chapter<Math.min(4,type-5))return false;const p=addPet(type);if(!p)return false;S.gold-=cost;saveGame(false);refreshBars();return p}
petsPanel=function(tab='bag'){if(!S)return;const showShop=tab==='shop';showDialog(panelHead('灵兽包裹')+`<div class="realm-tabs"><button id="petBagTab" class="${!showShop?'selected':''}">我的灵兽 ${S.pets.length}/100</button><button id="petShopTab" class="${showShop?'selected':''}">五行灵宠阁</button><button id="petFusionTab">灵兽合体</button></div><p>未骑乘的灵兽保存在包裹中；每位英雄可装备一只，重复收集保留为独立灵兽。骑乘战斗获得经验，10级可参与合体。</p><div class="pet-grid">`+(showShop?PETS.slice(0,12).map((p,type)=>`<article><div class="pet-portrait pet-idle" style="${petCardStyle(type)}"></div><h3>${p.name}</h3><p>${p.bonus}</p><button data-petbuy6="${type}" ${!atCamp()||S.gold<150+type*115||type>4&&S.chapter<Math.min(4,type-5)?'disabled':''}>契约 ${150+type*115}金</button></article>`).join(''):S.pets.map(p=>{const owner=S.heroes.findIndex(h=>h.pet===p.id);return `<article class="${p.type>=15?'pet-mythic':''}"><div class="pet-portrait pet-idle" style="${petCardStyle(p.type)}"></div><h3>${PETS[p.type].name}</h3><p>Lv.${p.lv} ${p.fusion?'✦'.repeat(p.fusion.stars):''} · ${owner<0?'包裹待命':HEROES[owner].name+'骑乘'}</p><p>${PETS[p.type].bonus}</p><label>分配骑乘<select data-petassign6="${p.id}" aria-label="分配${PETS[p.type].name}编号${p.id}"><option value="-1" ${owner<0?'selected':''}>放入包裹</option>${HEROES.map((h,i)=>owned(i)?`<option value="${i}" ${owner===i?'selected':''}>${h.name}</option>`:'').join('')}</select></label></article>`}).join('')||'<p class="empty-state">包裹空空如也。去五行灵宠阁挑选伙伴，或击败妖兽寻找灵兽。</p>')+'</div>');
 $('#petBagTab').onclick=()=>petsPanel();$('#petShopTab').onclick=()=>petsPanel('shop');$('#petFusionTab').onclick=fusionPanel;$('#dialog').querySelectorAll('[data-petassign6]').forEach(b=>b.onchange=()=>{assignPet(+b.dataset.petassign6,+b.value);petsPanel()});$('#dialog').querySelectorAll('[data-petbuy6]').forEach(b=>b.onclick=()=>{if(petPurchase(+b.dataset.petbuy6))petsPanel('shop')});
};
fusionPanel=function(){const ready=S.pets.filter(p=>p.lv>=10);showDialog(panelHead('万灵熔炉')+`<p>选择两只<strong>不同种类、10级以上</strong>灵兽，消耗250金币尝试合体。成功消耗双方，随机产生合体灵兽，等级取平均；失败消耗材料二，材料一保留并下降1级。幸运值由<strong>当前英雄武器上的天运石</strong>提供。</p><div class="fusion-select"><label>材料一<select id="fusionA">${ready.map(p=>`<option value="${p.id}">${PETS[p.type].name} Lv.${p.lv} #${p.id}</option>`).join('')}</select></label><span>✦</span><label>材料二<select id="fusionB">${ready.map(p=>`<option value="${p.id}">${PETS[p.type].name} Lv.${p.lv} #${p.id}</option>`).join('')}</select></label></div><div id="fusionOdds" class="fusion-odds"></div><button id="fusionPreview" class="primary" ${ready.length<2?'disabled':''}>预览合体</button><button id="fusionBack">返回包裹</button>`);if(ready.length>1)$('#fusionB').value=ready.find(p=>p.type!==ready[0].type)?.id||ready[1].id;
 const selected=()=>[S.pets.find(p=>p.id===+$('#fusionA').value),S.pets.find(p=>p.id===+$('#fusionB').value)];const updateOdds=()=>{const[a,b]=selected();if(!a||!b||a===b||a.type===b.type){$('#fusionOdds').textContent='请选择两只不同种类的灵兽。';return}const o=fusionOdds(a,b);$('#fusionOdds').innerHTML=`<div><small>当前英雄幸运</small><b>${o.luck}</b></div><div><small>合体成功率</small><b>${Math.round(o.success*1000)/10}%</b></div><div><small>成功后稀有变异率</small><b>${Math.round(o.rare*1000)/10}%</b></div>`};$('#fusionA').onchange=$('#fusionB').onchange=updateOdds;updateOdds();$('#fusionBack').onclick=()=>petsPanel();$('#fusionPreview').onclick=()=>{const[a,b]=selected();if(!a||!b||a===b||a.type===b.type)return;const o=fusionOdds(a,b);showDialog(panelHead('合体仪式')+`<div class="fusion-orbit"><span>✧</span><b>${Math.round(o.success*1000)/10}<small>% 成功率</small></b><span>✧</span></div><p>${PETS[a.type].name} Lv.${a.lv} + ${PETS[b.type].name} Lv.${b.lv} · 250金币。成功后有 ${Math.round(o.rare*1000)/10}% 概率稀有变异。失败会失去材料二，材料一下降1级。</p><p>可能诞生：${[...new Set(fusionPool(a,b))].map(t=>PETS[t].name).join('、')}，或四种稀有变异灵兽。</p><button id="confirmFusion6" class="primary" ${S.gold<250?'disabled':''}>开始合体</button><button id="cancelFusion6">返回选择</button>`);$('#cancelFusion6').onclick=fusionPanel;$('#confirmFusion6').onclick=()=>{const outcome=fusePets(a.id,b.id);if(!outcome)return;showDialog(panelHead(outcome.success?'灵契新生':'灵契未成')+(outcome.success?`<div class="fusion-result pet-idle" style="${petCardStyle(outcome.pet.type)}"></div><h3>${PETS[outcome.pet.type].name} · Lv.${outcome.pet.lv}</h3><p>${outcome.pet.type>=15?'稀有变异！新灵兽拥有更强的基础能力。':'新灵兽已收入包裹。'}</p>`:`<div class="fusion-failed">◇</div><p>材料一 ${PETS[a.type].name} 已保留，等级降为 ${a.lv}。材料二与250金币已消耗。提高当前英雄的幸运值可增加下次成功率。</p>`)+`<button id="fusionDone">返回灵兽包裹</button>`);$('#fusionDone').onclick=()=>petsPanel()}};
};

