 $('#realmSkills').innerHTML=[['attack','J','⚔','攻击'],['0','Q','✦','技能一'],['1','E','✧','技能二'],['2','R','✺','绝技'],['guard','G','◈','防御'],['dodge','空格','➶','闪避'],['potion','H','✚','药剂'],['ascend','T','❖','觉醒']].map(([id,key,icon,label])=>`<button id="action6-${id}" data-fast-action="${id}" aria-label="${label}"><kbd>${key}</kbd><i>${icon}</i><small id="label6-${id}">${label}</small><b class="action-cd" id="cd6-${id}"></b></button>`).join('');
