function petAbility(i=S.active,manual=true){if(!S||menu||!owned(i))return false;const a=actors[i],pet=petOf(i);if(!pet||a.hp<=0||a.petCd>0)return false;const target=nearestEnemy(a,manual?440:330);if(!target){if(manual){a.petMode='roar';a.petAnim=1.1;a.petCd=2;petFx.push({kind:'roar',x:a.x,y:a.y-65,color:PETS[pet.type].color,t:1.1,max:1.1})}return false}const breath=[3,4,11,12,15,18].includes(pet.type),magic=[8,9,10,14,17].includes(pet.type),power=stats(i).atk*.8+pet.lv*5+(pet.fusion?.stars||0)*35;const kind=breath?'breath':magic?'pulse':'pounce';a.petCd=manual?8:10;a.petMode=kind;a.petAnim=1.25;a.face=target.x>=a.x?1:-1;const x=a.x+a.face*48,y=a.y-70;petFx.push({kind,x,y,tx:target.x,ty:target.y-35,color:PETS[pet.type].color,t:1.8,max:1.8,seed:pet.id});
 const hits=enemies.filter(e=>e.map===currentMap()&&!e.dead&&dist(e,target)<(breath?100:magic?130:1));if(!hits.includes(target))hits.push(target);for(const enemy of hits)enemyDamage(enemy,power*(breath?.85:magic?.7:1.1),i,i);tone(breath?95:220,.15,'triangle');return true}
